parameters.jsCode:
const e = $input.first().json;
const wf = e.workflow?.name || 'desconocido';
const exec = e.execution?.id || 'n/a';
const err = e.execution?.error?.message || 'Error sin mensaje';
const last = e.execution?.lastNodeExecuted || 'n/a';
return [{ json: { workflow: wf, execution: exec, error: err, node: last, ts: new Date().toISOString() } }];

